#!/usr/bin/env python3
"""Compact dump of paragraphs 0-15."""
from pathlib import Path
from xml.dom import minidom

dom = minidom.parseString((Path("unpacked") / "word" / "document.xml").read_text(encoding="utf-8"))
paras = dom.getElementsByTagName("w:p")
for i, p in enumerate(paras[:16]):
    runs = p.getElementsByTagName("w:r")
    parts = []
    for r in runs:
        rpr = r.getElementsByTagName("w:rPr")
        flags = []
        if rpr:
            for ch in rpr[0].childNodes:
                if ch.nodeType == ch.ELEMENT_NODE:
                    flags.append(ch.tagName.replace("w:", ""))
        texts = []
        for t in r.getElementsByTagName("w:t"):
            texts.append(t.firstChild.nodeValue if t.firstChild else "")
        parts.append("{" + ",".join(flags) + "}" + "".join(texts))
    print(f"[{i}] " + " | ".join(parts))

